previewCss:
.darma-loader-darma-b15-taco-fold { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #84cc16); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .68); position: relative; }
.darma-loader-darma-b15-taco-fold .darma-loader-darma-b15-taco-fold__floor { position: absolute; left: 26%; right: 26%; bottom: 22%; height: 8%; border-radius: 0 0 8px 8px; background: color-mix(in srgb, #000 12%, var(--accent)); }
.darma-loader-darma-b15-taco-fold .darma-loader-darma-b15-taco-fold__side { position: absolute; bottom: 22%; width: 26%; height: 46%; background: linear-gradient(color-mix(in srgb, #fff 18%, var(--accent)), var(--accent)); }
.darma-loader-darma-b15-taco-fold .darma-loader-darma-b15-taco-fold__side:nth-of-type(1) { left: 22%; border-radius: 60% 8% 4% 4% / 90% 12% 4% 4%; transform-origin: 100% 100%; animation: darma-loader-darma-b15-taco-fold-taco-left calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b15-taco-fold .darma-loader-darma-b15-taco-fold__side:nth-of-type(2) { right: 22%; border-radius: 8% 60% 4% 4% / 12% 90% 4% 4%; transform-origin: 0 100%; animation: darma-loader-darma-b15-taco-fold-taco-right calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b15-taco-fold i { position: absolute; bottom: 30%; width: 12%; height: 12%; border-radius: 40%; background: var(--accent-2); transform: scale(0); animation: darma-loader-darma-b15-taco-fold-taco-fill calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b15-taco-fold i:nth-of-type(1) { left: 36%; }
.darma-loader-darma-b15-taco-fold i:nth-of-type(2) { left: 46%; bottom: 40%; background: #dc2626; animation-delay: calc(var(--loader-speed, 1s) * .16); }
.darma-loader-darma-b15-taco-fold i:nth-of-type(3) { left: 56%; animation-delay: calc(var(--loader-speed, 1s) * .32); }
@keyframes darma-loader-darma-b15-taco-fold-taco-left { 0%, 20% { transform: rotate(-42deg); } 52%, 80% { transform: rotate(0deg); } 100% { transform: rotate(-42deg); } }
@keyframes darma-loader-darma-b15-taco-fold-taco-right { 0%, 20% { transform: rotate(42deg); } 52%, 80% { transform: rotate(0deg); } 100% { transform: rotate(42deg); } }
@keyframes darma-loader-darma-b15-taco-fold-taco-fill { 0%, 24% { transform: scale(0); opacity: 0; } 44%, 78% { transform: scale(1); opacity: 1; } 94%, 100% { transform: scale(0); opacity: 0; } }

